assertThat(offsetDateTimeA).isEqualToIgnoringHours(offsetDateTimeB);

// Failing assertions occur even when the time difference is only 1 ms:
OffsetDateTimeA = 2000-01-02T00:00:00Z;
OffsetDateTimeB = 2000-01-01T23:59:59.999Z;
assertThat(OffsetDateTimeA).isEqualToIgnoringHours(OffsetDateTimeB);

